def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = set(v for row in grid for v in row) - {background}
    candidates = []

    for color in colors:
        # Enumerate solid-looking rectangles; small stray pixels are treated as
        # defects in an otherwise rectangular object.
        for r0 in range(h):
            for r1 in range(r0 + 1, h):
                height = r1 - r0 + 1
                for c0 in range(w):
                    for c1 in range(c0 + 1, w):
                        width = c1 - c0 + 1
                        area = height * width
                        count = sum(grid[r][c] == color
                                    for r in range(r0, r1 + 1)
                                    for c in range(c0, c1 + 1))
                        if count < 4 or count / area < 0.72:
                            continue
                        if any(not any(grid[r][c] == color
                                       for c in range(c0, c1 + 1))
                               for r in range(r0, r1 + 1)):
                            continue
                        if any(not any(grid[r][c] == color
                                       for r in range(r0, r1 + 1))
                               for c in range(c0, c1 + 1)):
                            continue
                        candidates.append((count, area, color, r0, r1, c0, c1))

    candidates.sort(reverse=True)
    owner = [[None] * w for _ in range(h)]
    for count, area, color, r0, r1, c0, c1 in candidates:
        # Do not let a weaker overlapping rectangle overwrite an established one.
        if any(owner[r][c] not in (None, color)
               for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)):
            continue
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                owner[r][c] = color

    return [[owner[r][c] if owner[r][c] is not None else background
             for c in range(w)] for r in range(h)]
